const context = options.contextData;
const viewmodel = context.viewmodel;
const editLevel = context.documentationEnums.EditLevels.FullAllow;
const selectedElement = context.selectedElement;
const resultSettings = {
	hidden: true
};

if (selectedElement && viewmodel.IsEqualEditableLevel(editLevel)) {
	const modelCursor = viewmodel.Cursor();

	if (selectedElement.is('ArasTextXmlSchemaElement') && selectedElement === modelCursor.commonAncestor) {
		const additionalData = target.additional_data || {};
		if (additionalData.actionParameters) {
			const rangeStyle = selectedElement.GetStyleOfRange() || {};
			const targetStyle = additionalData.actionParameters.actionName;
			resultSettings.state = Boolean(rangeStyle[targetStyle]);
		}
		resultSettings.hidden = false;
	}
}

return resultSettings;
